const GI_CATEGORIES=[{key:"agricultural",name:"Agricultural",icon:"🌾",desc:"Crops, fruits, spices and plantation produce whose taste and quality come from a specific soil, altitude and climate."},{key:"handicraft",name:"Handicraft",icon:"🎨",desc:"Objects made by hand using skills passed down through generations of artisan families in a defined region."},{key:"textile",name:"Textile",icon:"🧵",desc:"Woven, dyed and embroidered fabrics identified by weave structure, motif vocabulary and loom tradition."},{key:"foodstuff",name:"Foodstuff",icon:"🍬",desc:"Prepared foods and sweets whose recipe, ingredients and method belong to a particular town or community."},{key:"manufactured",name:"Manufactured",icon:"⚙️",desc:"Processed goods such as oils, beverages and metalware produced using region-specific raw material and technique."},{key:"natural",name:"Natural Goods",icon:"⛰️",desc:"Naturally occurring goods — stone, clay and minerals — whose properties are tied to their place of origin."}],GI_PRODUCTS=[{name:"Darjeeling Tea",state:"West Bengal",category:"agricultural",year:2004,icon:"🍵",tagline:"India's very first GI",desc:"Grown on misty slopes between 600 and 2,000 m in the Darjeeling hills, this light-bodied tea with its muscatel flavour became the first Indian product to receive a GI tag."},{name:"Alphonso Mango (Hapus)",state:"Maharashtra",category:"agricultural",year:2018,icon:"🥭",tagline:"The king of mangoes",desc:"Grown in the Konkan belt of Ratnagiri, Sindhudurg, Raigad and Palghar, where laterite soil and sea breeze give the fruit its saffron pulp and distinctive aroma."},{name:"Basmati Rice",state:"Indo-Gangetic Plains",category:"agricultural",year:2016,icon:"🍚",tagline:"Aromatic long-grain rice",desc:"A GI covering the Himalayan foothill belt across Punjab, Haryana, Himachal Pradesh, Uttarakhand, Delhi, western Uttar Pradesh and parts of Jammu & Kashmir."},{name:"Kashmir Saffron",state:"Jammu & Kashmir",category:"agricultural",year:2020,icon:"🌺",tagline:"Grown on the Pampore karewas",desc:"Cultivated on the elevated karewa tablelands around Pampore, Kashmiri saffron is prized for unusually high crocin content, which gives it deep colour and strong aroma."},{name:"Sikkim Large Cardamom",state:"Sikkim",category:"agricultural",year:2015,icon:"🌿",tagline:"Queen of spices",desc:"Shade-grown under Himalayan forest cover, Sikkim large cardamom is smoke-cured over slow fires, giving the capsules their characteristic resinous, smoky note."},{name:"Naga Mircha (King Chilli)",state:"Nagaland",category:"agricultural",year:2008,icon:"🌶️",tagline:"Among the hottest chillies on earth",desc:"The Bhut Jolokia of the Naga hills, once recorded as the world's hottest chilli, grown in the humid hill slopes of Nagaland and neighbouring states."},{name:"Muzaffarpur Shahi Litchi",state:"Bihar",category:"agricultural",year:2018,icon:"🍒",tagline:"Thin skin, high sugar",desc:"The calcium-rich alluvial soil of the Muzaffarpur belt produces a litchi with unusually thin skin, small seed and a rose-like fragrance."},{name:"Araku Valley Arabica Coffee",state:"Andhra Pradesh",category:"agricultural",year:2019,icon:"☕",tagline:"Tribal-grown shade coffee",desc:"Organically cultivated by tribal farmer cooperatives in the Eastern Ghats, grown under natural shade at 900–1,100 m in the Araku Valley."},{name:"Allahabad Surkha Guava",state:"Uttar Pradesh",category:"agricultural",year:2016,icon:"🍈",tagline:"Pink-fleshed guava",desc:"A guava variety of the Prayagraj region with red-pink flesh and a sweet-tart balance, ripening in the cool north Indian winter."},{name:"Chak-Hao (Manipur Black Rice)",state:"Manipur",category:"agricultural",year:2020,icon:"🌾",tagline:"Scented black rice",desc:"A deep-purple aromatic rice traditionally served at Manipuri feasts, rich in anthocyanins and cooked slowly because of its unmilled bran layer."},{name:"Kangra Tea",state:"Himachal Pradesh",category:"agricultural",year:2005,icon:"🍃",tagline:"Himalayan orthodox tea",desc:"Grown in the Kangra Valley beneath the Dhauladhar range, producing a light liquor with a sweet lingering aftertaste from slow high-altitude growth."},{name:"Kanniyakumari Clove",state:"Tamil Nadu",category:"agricultural",year:2023,icon:"🌰",tagline:"High oil content",desc:"Grown on the Western Ghats slopes of Kanniyakumari district, this clove has notably high volatile oil content compared with other Indian cloves."},{name:"Marayoor Jaggery",state:"Kerala",category:"agricultural",year:2019,icon:"🟤",tagline:"No chemicals, high sweetness",desc:"Made in the Marayoor valley of Idukki from sugarcane grown in mineral-rich soil, processed without chemical clarifiers into dark, mineral-heavy jaggery."},{name:"Aranmula Kannadi",state:"Kerala",category:"handicraft",year:2004,icon:"🪞",tagline:"The metal mirror",desc:"A front-surface mirror cast from a secret alloy by a handful of families in Aranmula — it reflects without the parallax of a glass mirror."},{name:"Bidriware",state:"Karnataka",category:"handicraft",year:2005,icon:"⚱️",tagline:"Silver inlay on blackened alloy",desc:"Zinc-copper alloy vessels inlaid with silver, then blackened using soil from Bidar fort — the soil's composition is what makes the process work only there."},{name:"Madhubani Painting",state:"Bihar",category:"handicraft",year:2007,icon:"🖼️",tagline:"Mithila wall art",desc:"Originally painted on the mud walls of Mithila homes for weddings and festivals, using natural pigments and dense line work with no empty space left."},{name:"Channapatna Toys",state:"Karnataka",category:"handicraft",year:2005,icon:"🪀",tagline:"Karnataka's toy town",desc:"Lacquered wooden toys turned on hand lathes from ivory-wood, coloured with vegetable dyes — a craft encouraged by Tipu Sultan in the 18th century."},{name:"Blue Pottery of Jaipur",state:"Rajasthan",category:"handicraft",year:2008,icon:"🏺",tagline:"Fired without clay",desc:"Made from quartz powder, fuller's earth and borax rather than clay, glazed in cobalt blue and copper turquoise — a Persian technique adapted in Jaipur."},{name:"Kondapalli Bommallu",state:"Andhra Pradesh",category:"handicraft",year:2006,icon:"🪆",tagline:"Softwood figurines",desc:"Carved from the light Tella Poniki wood by the Aryakshatriya community of Kondapalli, depicting village life, mythological scenes and Dasara displays."},{name:"Etikoppaka Toys",state:"Andhra Pradesh",category:"handicraft",year:2017,icon:"🎠",tagline:"Natural-dye lacquerware",desc:"Turned from Ankudu wood on a lathe and coloured with dyes made from seeds, bark and roots, making them safe for small children."},{name:"Kashmir Walnut Wood Carving",state:"Jammu & Kashmir",category:"handicraft",year:2011,icon:"🪵",tagline:"Deep-relief woodwork",desc:"Carved from Kashmiri walnut, one of the few woods dense enough for undercut lattice and deep-relief work, on furniture, screens and panels."},{name:"Konark Stone Carving",state:"Odisha",category:"handicraft",year:2018,icon:"🗿",tagline:"Heirs of the Sun Temple",desc:"The stone-carving tradition of the Konark region, continuing the chlorite and khondalite sculpting techniques used on the 13th-century Sun Temple."},{name:"Sohrai Khovar Painting",state:"Jharkhand",category:"handicraft",year:2020,icon:"🐄",tagline:"Harvest and marriage murals",desc:"Painted by tribal women of the Hazaribagh region on house walls with local ochre and clay — Sohrai for the harvest, Khovar for weddings."},{name:"Warli Painting",state:"Maharashtra",category:"handicraft",year:2014,icon:"🎭",tagline:"Circles, triangles and lines",desc:"The Warli tribe's ritual painting built from three shapes, executed in rice paste on cow-dung-washed walls to record daily life and the tarpa dance."},{name:"Pattachitra",state:"Odisha",category:"handicraft",year:2008,icon:"📜",tagline:"Cloth-scroll painting",desc:"Painted on a treated cloth-and-tamarind-paste canvas by the chitrakars of Raghurajpur, illustrating Jagannath legends in mineral colours."},{name:"Kolhapuri Chappal",state:"Maharashtra & Karnataka",category:"handicraft",year:2019,icon:"👡",tagline:"Vegetable-tanned leather",desc:"A joint GI covering districts of both states, made from vegetable-tanned leather stitched entirely by hand without nails or synthetic adhesive."},{name:"Kancheepuram Silk",state:"Tamil Nadu",category:"textile",year:2005,icon:"🥻",tagline:"Woven with three shuttles",desc:"Body and border are woven separately and interlocked, so the joint survives even if the saree tears — the korvai technique unique to Kancheepuram."},{name:"Banarasi Brocade & Saree",state:"Uttar Pradesh",category:"textile",year:2009,icon:"✨",tagline:"Zari-woven Mughal motifs",desc:"Handloom brocade from Varanasi with gold and silver zari, dense floral jaal, kalga and bel motifs traced to Mughal-era design books."},{name:"Pochampally Ikat",state:"Telangana",category:"textile",year:2004,icon:"🧶",tagline:"Tie-dyed before weaving",desc:"Yarn is resist-dyed to the exact pattern before it goes on the loom, so the geometric motif appears identically on both faces of the cloth."},{name:"Kashmir Pashmina",state:"Jammu & Kashmir",category:"textile",year:2008,icon:"🧣",tagline:"Hand-spun Changthangi wool",desc:"Spun from the undercoat of the Changthangi goat of Ladakh at 12–16 microns, hand-spun on a yinder and hand-woven in the Kashmir Valley."},{name:"Chanderi Saree",state:"Madhya Pradesh",category:"textile",year:2005,icon:"🪡",tagline:"Sheer as woven air",desc:"Its transparency comes from using unbleached, un-degummed yarn, giving Chanderi its glassy sheen and famously low weight."},{name:"Mysore Silk",state:"Karnataka",category:"textile",year:2005,icon:"🎽",tagline:"Pure mulberry silk and gold zari",desc:"Woven from 100% pure mulberry silk with genuine gold zari, produced under the state silk factory established by the Mysore royal house in 1912."},{name:"Kullu Shawl",state:"Himachal Pradesh",category:"textile",year:2004,icon:"🧥",tagline:"Geometric patti borders",desc:"Woven on pit looms in the Kullu Valley with bold geometric end-borders in eight colours, originally an unpatterned Kullu wrap until 20th-century weavers added the patti."},{name:"Assam Muga Silk",state:"Assam",category:"textile",year:2007,icon:"🟡",tagline:"Golden silk that never fades",desc:"Produced by the semi-domesticated Antheraea assamensis moth, Muga has a natural golden sheen that deepens with every wash and cannot be dyed."},{name:"Telia Rumal",state:"Telangana",category:"textile",year:2020,icon:"🟥",tagline:"Oil-treated double ikat",desc:"Yarn is treated with sesame oil and ash for weeks before dyeing, producing a soft cloth once exported across the Arabian Sea and worn as a headcloth."},{name:"Sambalpuri Bandha Saree",state:"Odisha",category:"textile",year:2010,icon:"🌀",tagline:"Western Odisha tie-dye",desc:"Bandha ikat sarees of Sambalpur, Bargarh and Sonepur, where shankha, chakra and phula motifs are dyed into the yarn before weaving."},{name:"Kandangi Saree",state:"Tamil Nadu",category:"textile",year:2019,icon:"🟧",tagline:"Chettinad cotton checks",desc:"Woven in the Karaikudi region with wide contrast borders and bold checks, in heavy cotton suited to the dry Chettinad climate."},{name:"Tirupati Laddu",state:"Andhra Pradesh",category:"foodstuff",year:2009,icon:"🟠",tagline:"Temple prasadam with a GI",desc:"The laddu offered at the Tirumala Venkateswara temple, made in the temple's own potu kitchen — the GI was sought to stop imitation sales outside."},{name:"Bikaneri Bhujia",state:"Rajasthan",category:"foodstuff",year:2010,icon:"🥨",tagline:"Moth-bean savoury",desc:"A spiced moth-bean-flour snack originating in the princely kitchens of Bikaner in the 1870s, now a byword for the city itself."},{name:"Odisha Rasagola",state:"Odisha",category:"foodstuff",year:2019,icon:"⚪",tagline:"The Puri temple sweet",desc:"Softer, browner and less spongy than its Bengal counterpart, traditionally offered at the Jagannath temple in the Niladri Bije ritual."},{name:"Banglar Rasogolla",state:"West Bengal",category:"foodstuff",year:2017,icon:"🤍",tagline:"The other rasogolla",desc:"Bengal's white, spongy chhena sweet — both states hold GI tags for their own distinct versions, resolving a long-running rivalry."},{name:"Dharwad Pedha",state:"Karnataka",category:"foodstuff",year:2009,icon:"🟫",tagline:"Caramelised milk sweet",desc:"Made by slow-browning khoa until it caramelises, a technique brought to Dharwad by the Thakur family from Uttar Pradesh in the 19th century."},{name:"Joynagar Moa",state:"West Bengal",category:"foodstuff",year:2015,icon:"🟡",tagline:"Winter-only sweet",desc:"Made only in winter from kanakchur khoi puffed rice and fresh nolen gur date-palm jaggery, which is available for just a few weeks a year."},{name:"Palani Panchamirtham",state:"Tamil Nadu",category:"foodstuff",year:2019,icon:"🍯",tagline:"Five-ingredient offering",desc:"The prasadam of the Palani Murugan temple — banana, jaggery, ghee, honey and cardamom, made without a drop of water, so it keeps for months."},{name:"Bardhaman Sitabhog & Mihidana",state:"West Bengal",category:"foodstuff",year:2017,icon:"🍮",tagline:"Created for a viceroy",desc:"Both sweets were reportedly created in Bardhaman in 1904 to mark a viceregal visit and have been made by the same confectioner families since."},{name:"Mysore Sandalwood Oil",state:"Karnataka",category:"manufactured",year:2005,icon:"🧴",tagline:"Distilled since 1916",desc:"Steam-distilled from Santalum album heartwood at the Mysore government factory set up in 1916, when the First World War cut off sandalwood exports."},{name:"Goa Feni",state:"Goa",category:"manufactured",year:2009,icon:"🥃",tagline:"Cashew-apple spirit",desc:"Triple-distilled from cashew apples or coconut toddy in earthen or copper pots — the first Indian alcoholic drink to receive a GI tag."},{name:"Nashik Valley Wine",state:"Maharashtra",category:"manufactured",year:2010,icon:"🍷",tagline:"India's wine capital",desc:"Wines from the Nashik plateau, where altitude and a dry harvest season allow the long, cool ripening that table-wine grapes need."},{name:"Thanjavur Art Plate",state:"Tamil Nadu",category:"manufactured",year:2007,icon:"🥇",tagline:"Silver and copper on brass",desc:"Decorative plates layered with embossed silver and copper figures on a brass base, developed under the patronage of the Thanjavur Maratha rulers."},{name:"Firozabad Glass",state:"Uttar Pradesh",category:"manufactured",year:2015,icon:"🫧",tagline:"The glass city",desc:"Hand-blown and lampworked glass from Firozabad, which supplies a large share of the country's bangles, beads and decorative glassware."},{name:"Makrana Marble",state:"Rajasthan",category:"natural",year:2015,icon:"⬜",tagline:"The stone of the Taj Mahal",desc:"Calcite marble from the Makrana quarries of Nagaur, near-free of impurities and non-porous — quarried for the Taj Mahal and the Victoria Memorial."},{name:"Kota Doria Stone",state:"Rajasthan",category:"natural",year:2005,icon:"🪨",tagline:"Kota limestone",desc:"Fine-grained limestone from the Kota region, split into thin, hard-wearing slabs that have paved courtyards and stepwells across Rajasthan."}],GI_TIMELINE=[{year:"1999",title:"The GI Act is passed",desc:"Parliament enacts the Geographical Indications of Goods (Registration and Protection) Act to meet India's obligations under the WTO TRIPS agreement."},{year:"2003",title:"The Act comes into force",desc:"The GI Registry opens in Chennai under the Controller General of Patents, Designs and Trade Marks, and begins accepting applications."},{year:"2004",title:"Darjeeling Tea registered",desc:"Darjeeling Tea becomes the first Indian product on the GI register, following years of international disputes over misuse of the name."},{year:"2005",title:"Craft and textile GIs arrive",desc:"Kancheepuram Silk, Mysore Silk, Chanderi, Channapatna Toys, Bidriware and Mysore Sandalwood Oil are registered in quick succession."},{year:"2008",title:"Pashmina protected",desc:"Kashmir Pashmina receives GI protection, giving Valley weavers a legal basis to challenge machine-spun imitations sold under the name."},{year:"2010",title:"GI reaches food and drink",desc:"Bikaneri Bhujia, Goa Feni and Nashik Valley Wine show that the system covers prepared foods and beverages, not only crafts and crops."},{year:"2017",title:"The rasogolla question",desc:"West Bengal receives a GI for Banglar Rasogolla; Odisha follows in 2019 with Odisha Rasagola, and both traditions are recognised as distinct."},{year:"2020",title:"A record year",desc:"Kashmir Saffron, Chak-Hao black rice, Sohrai Khovar painting, Telia Rumal and Gorakhpur Terracotta are all added within a single year."},{year:"2023",title:"Past 600 registrations",desc:"India crosses 600 registered GIs, with Karnataka and Tamil Nadu holding the largest state tallies and handicrafts the largest category."}],GI_PROCESS=[{step:1,title:"Who can apply",desc:"Only an association of producers, a cooperative, or an authority representing them — never a single individual or company. The GI belongs to the community.",icon:"👥"},{step:2,title:"The statement of case",desc:"The application must prove the link between the product and the place: history, the exact geographic boundary, the production method and the quality that follows from it.",icon:"📄"},{step:3,title:"Examination",desc:"The GI Registry in Chennai examines the claim and a consultative group of experts scrutinises the evidence before an examination report is issued.",icon:"🔍"},{step:4,title:"Publication and opposition",desc:"Accepted applications are published in the GI Journal. Anyone may oppose the registration within three months of publication.",icon:"📢"},{step:5,title:"Registration",desc:"If unopposed or upheld, the GI is entered on the register and a certificate is issued. Protection runs for 10 years and can be renewed indefinitely.",icon:"🏅"},{step:6,title:"Authorised users",desc:"Individual producers within the region register separately as authorised users. Only they may legally apply the GI to goods they sell.",icon:"✅"}],GI_COMPARISON=[{aspect:"Who owns it",gi:"A community of producers in a defined region — no single owner",trademark:"One business or individual",patent:"The inventor or their assignee"},{aspect:"What it signals",gi:"Origin, and the quality that origin produces",trademark:"Commercial source — which firm made it",patent:"A new, non-obvious, useful invention"},{aspect:"Can it be sold",gi:"No — it cannot be assigned, licensed or transferred",trademark:"Yes, freely assignable and licensable",patent:"Yes, assignable and licensable"},{aspect:"How long it lasts",gi:"10 years, renewable indefinitely",trademark:"10 years, renewable indefinitely",patent:"20 years, non-renewable"}],GI_BENEFITS=[{title:"Legal protection against imitation",icon:"⚖️",desc:"A registered GI gives producers standing to act against goods falsely sold under the regional name, in India and in partner jurisdictions."},{title:"Better prices for artisans",icon:"💰",desc:"Verified origin lets producers command a premium instead of competing on price with mass-produced lookalikes."},{title:"Keeping skills alive",icon:"🪡",desc:"When a craft becomes economically viable again, young people in artisan families have a reason to learn it rather than migrate for other work."},{title:"Export credibility",icon:"🌍",desc:"GI status is recognised internationally under TRIPS, which helps Indian goods enter markets that treat origin labelling seriously."},{title:"Rural livelihoods",icon:"🏘️",desc:"Most GI production is rural and household-scale, so the value stays in small towns and villages rather than moving to industrial centres."},{title:"Cultural documentation",icon:"📚",desc:"The statement of case for each GI is a detailed record of technique and history — a research archive created as a side effect of registration."}],GI_CHALLENGES=[{title:"Few authorised users",icon:"📉",desc:"Many GIs are registered but have very few producers enrolled as authorised users, so the tag exists without reaching the artisan on the ground.",severity:"High"},{title:"Weak post-registration enforcement",icon:"🚨",desc:"Registration is only the first step; monitoring markets and litigating misuse needs money and legal capacity most producer bodies do not have.",severity:"Critical"},{title:"Low consumer awareness",icon:"🤷",desc:"Most buyers cannot recognise the GI logo or explain what it certifies, which limits the price premium the tag is supposed to create.",severity:"High"},{title:"Middlemen capture",icon:"🔗",desc:"Where traders control the route to market, the premium generated by GI status often does not reach the weaver or farmer who created the value.",severity:"Critical"},{title:"Overlapping claims",icon:"⚔️",desc:"Products made across state boundaries have produced contested applications, some of which have taken years to resolve.",severity:"Moderate"},{title:"Raw material scarcity",icon:"🌱",desc:"Some GIs depend on material that is itself running short — specific clays, dye plants or wood species — putting the craft at risk regardless of the tag.",severity:"High"}],GI_FACTS=["The GI Registry for the whole of India sits in a single office in Chennai, established in 2003.","A GI cannot be bought, sold or licensed — unlike a trademark, it is permanently tied to its region.","Darjeeling Tea was registered in 2004-05 as GI application number 1, making it India's first.","Karnataka and Tamil Nadu consistently hold the largest number of registered GIs among Indian states.","Handicrafts make up the largest single category of Indian GIs, ahead of agricultural goods.","Both Odisha and West Bengal hold GI tags for their own distinct versions of the rasogolla.","Goa Feni, registered in 2009, was the first Indian alcoholic beverage to receive a GI tag.","Makrana Marble, the stone used for the Taj Mahal, received its GI tag only in 2015.","A GI registration lasts 10 years but can be renewed without limit, so protection can be perpetual.","Assam's Muga silk cannot be dyed — its golden colour is natural and deepens with washing."],GI_QUIZ=[{q:"Which product was the first in India to receive a GI tag?",options:["Mysore Silk","Darjeeling Tea","Banarasi Saree","Alphonso Mango"],answer:1,explain:"Darjeeling Tea was registered in 2004-05 as India's first Geographical Indication."},{q:"Where is India's Geographical Indications Registry located?",options:["New Delhi","Mumbai","Chennai","Kolkata"],answer:2,explain:"The GI Registry has operated from Chennai since the Act came into force in 2003."},{q:"How long does a GI registration remain valid before renewal?",options:["5 years","10 years","20 years","Permanently, no renewal needed"],answer:1,explain:"A GI is valid for 10 years and may be renewed indefinitely in 10-year blocks."},{q:"Which of these is TRUE of a GI but not of a trademark?",options:["It can be licensed to any company","It belongs to a community of producers and cannot be assigned","It lasts only 20 years","It protects an invention"],answer:1,explain:"A GI is a collective right tied to a region — it cannot be assigned, sold or licensed away."},{q:"Bidriware gets its characteristic black finish from what?",options:["Charcoal polish","Soil from Bidar fort","Iron oxide paint","Volcanic ash"],answer:1,explain:"The blackening paste uses soil from within Bidar fort, whose composition makes the process work."},{q:"Kashmir Saffron is grown chiefly on which landform?",options:["River deltas","Karewa tablelands","Coastal plains","Terraced paddy fields"],answer:1,explain:"Saffron is grown on the elevated karewa tablelands around Pampore in the Kashmir Valley."},{q:"Which was the first Indian alcoholic beverage to receive a GI tag?",options:["Nashik Valley Wine","Goa Feni","Toddy","Mahua liquor"],answer:1,explain:"Goa Feni, distilled from cashew apple or coconut toddy, received its GI in 2009."},{q:"Under which law are Geographical Indications registered in India?",options:["The Trade Marks Act, 1999","The Copyright Act, 1957","The Geographical Indications of Goods (Registration and Protection) Act, 1999","The Patents Act, 1970"],answer:2,explain:"The GI Act of 1999 was passed to meet India's WTO TRIPS obligations and took effect in 2003."}],GI_GALLERY=[{icon:"🍵",title:"Darjeeling Tea Gardens",caption:"Terraced tea slopes of the Darjeeling hills, West Bengal"},{icon:"🥻",title:"Kancheepuram Loom",caption:"A korvai border being interlocked on a Kancheepuram pit loom"},{icon:"🪞",title:"Aranmula Kannadi",caption:"The polished metal mirror of Aranmula, Kerala"},{icon:"🖼️",title:"Madhubani Wall Art",caption:"Mithila painting in natural pigment, Bihar"},{icon:"🥭",title:"Konkan Alphonso Orchards",caption:"Hapus mango orchards of the Ratnagiri coast, Maharashtra"},{icon:"🧣",title:"Pashmina Spinning",caption:"Hand-spinning Changthangi wool on a yinder, Kashmir"},{icon:"🪀",title:"Channapatna Lathe",caption:"Lacquered wooden toys turned on a hand lathe, Karnataka"},{icon:"🌺",title:"Pampore Saffron Fields",caption:"Saffron crocus flowering on the karewas, Jammu & Kashmir"}];